int[][] grid = {
    { 8, 7, 6, 7 },
    { 2, 8, 9, 1 },
    { 5, 1, 3, 9 }
};
int total = 0;
for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
        if (r == c) {
            total += grid[r][c];
        } else if (c > r) {
            total -= grid[r][c];
        }
    }
}
System.out.println(total);
```

